'use client'

import {
  BlockReady,
  BlockStateProvider,
  BlockStateText,
  type BlockStatus,
  getBlockState,
} from '@/registry/components/dashboardblocks/block-state'
import {
  ChartFloatingTooltip,
  ChartPlaceholder,
  ChartTooltipItem,
} from '@/registry/components/dashboardblocks/chart'
import {
  EventSwatch,
  type ScheduleEvent,
  addDays,
  formatDay,
  formatDuration,
  formatTimeRange,
  getDateParts,
  getDay,
  getDayKey,
  getEventStyle,
} from '@/registry/components/dashboardblocks/schedule'
import { useRef, useState } from 'react'

import { cn } from '@/lib/utils'

interface Schedule4Props {
  calendars: { color: string; name: string }[]
  /** Last hour on the axis, 1–24. */
  endHour?: number
  /** Leave out, or pass none, to show the empty state. */
  events?: ScheduleEvent[]
  now: Date
  /** First hour on the axis, 0–23. */
  startHour?: number
  status?: BlockStatus
  /** @default 'UTC' */
  timeZone?: string
  title: string
}

const NOW = Date.UTC(2026, 8, 28, 9, 40)
const at = (day: number, hour: number, minute = 0) =>
  new Date(Date.UTC(2026, 8, 28 + day, hour, minute))

const CALENDARS = {
  customers: { calendar: 'Customers', color: 'var(--color-chart-3)' },
  focus: { calendar: 'Focus', color: 'var(--color-chart-5)' },
  product: { calendar: 'Product', color: 'var(--color-chart-2)' },
  team: { calendar: 'Team', color: 'var(--color-chart-4)' },
}

const exampleProps: Schedule4Props = {
  calendars: Object.values(CALENDARS).map(({ calendar, color }) => ({
    color,
    name: calendar,
  })),
  events: [
    { ...CALENDARS.team, end: at(0, 9, 15), id: 'w1', start: at(0, 9), title: 'Standup' },
    {
      ...CALENDARS.product,
      end: at(0, 10, 30),
      id: 'w2',
      start: at(0, 9, 30),
      title: 'Roadmap review',
    },
    {
      ...CALENDARS.customers,
      end: at(0, 14, 45),
      id: 'w3',
      start: at(0, 14),
      title: 'Northwind onboarding',
    },
    {
      ...CALENDARS.focus,
      end: at(0, 17),
      id: 'w4',
      start: at(0, 15),
      title: 'Focus time',
    },
    { ...CALENDARS.team, end: at(1, 9, 15), id: 'w5', start: at(1, 9), title: 'Standup' },
    {
      ...CALENDARS.team,
      end: at(1, 13),
      id: 'w6',
      start: at(1, 12),
      title: 'Team lunch',
    },
    {
      ...CALENDARS.customers,
      end: at(1, 16, 30),
      id: 'w7',
      start: at(1, 15, 30),
      title: 'Acme QBR',
    },
    { ...CALENDARS.team, end: at(2, 9, 15), id: 'w8', start: at(2, 9), title: 'Standup' },
    {
      ...CALENDARS.product,
      end: at(2, 11),
      id: 'w9',
      start: at(2, 10),
      title: 'Design critique',
    },
    {
      ...CALENDARS.customers,
      end: at(2, 11, 30),
      id: 'w10',
      start: at(2, 10, 30),
      title: 'Initech demo',
    },
    {
      ...CALENDARS.product,
      end: at(2, 16),
      id: 'w11',
      start: at(2, 13),
      title: 'v4.2 release window',
    },
    {
      ...CALENDARS.team,
      end: at(3, 9, 15),
      id: 'w12',
      start: at(3, 9),
      title: 'Standup',
    },
    {
      ...CALENDARS.focus,
      end: at(3, 12),
      id: 'w13',
      start: at(3, 9, 30),
      title: 'Focus time',
    },
    {
      ...CALENDARS.team,
      end: at(4, 9, 15),
      id: 'w14',
      start: at(4, 9),
      title: 'Standup',
    },
    {
      ...CALENDARS.team,
      end: at(4, 17),
      id: 'w15',
      start: at(4, 16),
      title: 'Sprint retro',
    },
  ],
  now: new Date(NOW),
  title: 'Week ahead',
}

function assignLanes(events: ScheduleEvent[]) {
  const laneEnds: number[] = []
  return events.map((event) => {
    const start = event.start.getTime()
    const end = (event.end ?? event.start).getTime()
    let lane = laneEnds.findIndex((laneEnd) => laneEnd <= start)
    if (lane === -1) lane = laneEnds.length
    laneEnds[lane] = end
    return { event, lane }
  })
}

function getBookedMinutes(events: ScheduleEvent[]) {
  let total = 0
  let until = -Infinity
  for (const event of events) {
    const start = Math.max(event.start.getTime(), until)
    const end = (event.end ?? event.start).getTime()
    if (end > start) total += (end - start) / 60_000
    until = Math.max(until, end)
  }
  return total
}

const formatHour = (hour: number) =>
  `${hour % 12 || 12}${hour < 12 || hour === 24 ? 'a' : 'p'}`

interface HoveredEvent {
  event: ScheduleEvent
  flip: boolean
  x: number
  y: number
}

const Schedule4 = (props: Schedule4Props) => {
  const {
    calendars,
    endHour = 18,
    events = [],
    now,
    startHour = 8,
    status,
    timeZone = 'UTC',
    title,
  } = props
  const frame = useRef<HTMLDivElement>(null)
  const [hovered, setHovered] = useState<HoveredEvent | null>(null)
  const state = getBlockState(status, events)
  const today = getDay(now, timeZone)
  const range = (endHour - startHour) * 60
  const ticks = Array.from(
    { length: Math.floor((endHour - startHour) / 2) + 1 },
    (_, index) => startHour + index * 2,
  )
  const position = (date: Date) => {
    const { hour, minute } = getDateParts(date, timeZone)
    const minutes = hour * 60 + minute - startHour * 60
    return Math.min(1, Math.max(0, minutes / range)) * 100
  }

  const days = Array.from({ length: 7 }, (_, index) => {
    const day = addDays(today, index)
    const key = day.toISOString().slice(0, 10)
    const dayEvents = events
      .filter((event) => getDayKey(event.start, timeZone) === key)
      .sort((a, b) => a.start.getTime() - b.start.getTime())
    const timed = dayEvents.filter((event) => !event.allDay)
    return {
      allDay: dayEvents.filter((event) => event.allDay),
      booked: getBookedMinutes(timed),
      day,
      key,
      lanes: assignLanes(timed),
    }
  })
  const totalEvents = days.reduce(
    (sum, day) => sum + day.lanes.length + day.allDay.length,
    0,
  )
  const totalBooked = days.reduce((sum, day) => sum + day.booked, 0)
  const busiest = days.reduce((top, day) => (day.booked > top.booked ? day : top))
  const nowPosition = position(now)
  const booked = (minutes: number) =>
    minutes === 0 ? 'Free' : formatDuration(new Date(0), new Date(minutes * 60_000))
  const dayName = (day: Date, index: number) =>
    index === 0 ? 'today' : formatDay(day, { weekday: 'long' })

  const show = (event: ScheduleEvent, bar: HTMLElement) => {
    const origin = frame.current?.getBoundingClientRect()
    if (!origin) return
    const box = bar.getBoundingClientRect()
    const x = box.left - origin.left + box.width / 2
    setHovered({
      event,
      flip: x > origin.width / 2,
      x,
      y: box.top - origin.top + box.height / 2,
    })
  }

  return (
    <BlockStateProvider state={state}>
      <section className='@container flex flex-col gap-4'>
        <header className='flex flex-col gap-0.5'>
          <h2 className='font-semibold tracking-tight'>{title}</h2>
          <BlockReady className='text-sm'>
            <p className='text-muted-foreground text-sm'>
              {totalEvents} {totalEvents === 1 ? 'event' : 'events'} in the next 7 days,{' '}
              {totalBooked === 0 ? 'nothing' : booked(totalBooked)} booked.
              {busiest.booked > 0 && (
                <>
                  {' '}
                  The busiest day is {dayName(busiest.day, days.indexOf(busiest))}, with{' '}
                  {booked(busiest.booked)} of meetings.
                </>
              )}
            </p>
          </BlockReady>
        </header>
        <div ref={frame} className='relative flex flex-col gap-2 border-t pt-3'>
          <div
            aria-hidden
            className='text-muted-foreground grid grid-cols-1 text-xs tabular-nums @lg:grid-cols-[5rem_minmax(0,1fr)_11rem] @lg:gap-x-3'
          >
            <div className='relative h-4 @lg:col-start-2'>
              {ticks.map((hour) => (
                <span
                  key={hour}
                  className={cn(
                    'absolute -translate-x-1/2',
                    hour === startHour && 'translate-x-0',
                    hour === endHour && '-translate-x-full',
                  )}
                  style={{ left: `${(((hour - startHour) * 60) / range) * 100}%` }}
                >
                  {formatHour(hour)}
                </span>
              ))}
            </div>
          </div>
          {state === 'loading' && (
            <>
              <span className='sr-only'>Loading</span>
              <ChartPlaceholder height={272} />
            </>
          )}
          {state && state !== 'loading' && <BlockStateText className='py-2.5 text-sm' />}
          {!state && (
            <ol className='flex flex-col gap-3 @lg:gap-2'>
              {days.map(({ allDay, booked: minutes, day, key, lanes }, index) => {
                const laneCount = Math.max(1, ...lanes.map(({ lane }) => lane + 1))
                const count = lanes.length + allDay.length
                return (
                  <li
                    key={key}
                    className='grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-1.5 @lg:grid-cols-[5rem_minmax(0,1fr)_11rem]'
                  >
                    <h3 className='min-w-0 text-sm'>
                      <span aria-hidden className='font-medium'>
                        {index === 0
                          ? 'Today'
                          : `${formatDay(day, { weekday: 'short' })} ${day.getUTCDate()}`}
                      </span>
                      <span className='sr-only'>
                        {index === 0 && 'Today, '}
                        {formatDay(day, {
                          day: 'numeric',
                          month: 'long',
                          weekday: 'long',
                        })}
                      </span>
                      {allDay.map((event) => (
                        <span
                          key={event.id}
                          className='text-muted-foreground block truncate text-xs'
                        >
                          {event.title} (all day)
                        </span>
                      ))}
                    </h3>
                    <p className='text-muted-foreground flex justify-end gap-3 text-sm whitespace-nowrap tabular-nums @lg:order-last'>
                      {count === 0
                        ? 'No events'
                        : `${count} ${count === 1 ? 'event' : 'events'}`}
                      {count > 0 && (
                        <span className='hidden w-20 text-right @lg:inline'>
                          <span className='sr-only'>, </span>
                          {booked(minutes)}
                        </span>
                      )}
                    </p>
                    <div
                      className='bg-muted/30 relative col-span-2 rounded-md @lg:col-span-1'
                      style={{ height: `calc(${laneCount} * 1.5rem + 0.5rem)` }}
                    >
                      {ticks.slice(1, -1).map((hour) => (
                        <span
                          key={hour}
                          aria-hidden
                          className='bg-border absolute inset-y-0 w-px'
                          style={{
                            left: `${(((hour - startHour) * 60) / range) * 100}%`,
                          }}
                        />
                      ))}
                      <ul>
                        {lanes.map(({ event, lane }) => {
                          const left = Math.min(98, position(event.start))
                          const width = Math.max(
                            2,
                            position(event.end ?? event.start) - left,
                          )
                          const ended = (event.end ?? event.start) <= now
                          const minutes =
                            ((event.end ?? event.start).getTime() -
                              event.start.getTime()) /
                            60_000
                          return (
                            <li
                              key={event.id}
                              onPointerEnter={(pointer) =>
                                show(event, pointer.currentTarget)
                              }
                              onPointerDown={(pointer) =>
                                show(event, pointer.currentTarget)
                              }
                              onPointerLeave={() => setHovered(null)}
                              className={cn(
                                'absolute flex h-5 items-center overflow-hidden rounded-sm border-s-2 px-1 text-xs leading-none font-medium',
                                ended && 'text-muted-foreground',
                              )}
                              style={{
                                ...getEventStyle(event, ended, 'var(--color-background)'),
                                left: `${left}%`,
                                top: `calc(${lane} * 1.5rem + 0.25rem)`,
                                width: `${width}%`,
                              }}
                            >
                              <span className='sr-only'>
                                {formatTimeRange(event.start, event.end, timeZone)}
                                {event.calendar && `, ${event.calendar}`}
                                {ended && ', ended'}:{' '}
                              </span>
                              <span
                                className={cn(
                                  'truncate',
                                  minutes < 60 && 'sr-only',
                                  minutes < 120 && '@max-md:sr-only',
                                )}
                              >
                                {event.title}
                              </span>
                            </li>
                          )
                        })}
                      </ul>
                      {index === 0 && nowPosition > 0 && nowPosition < 100 && (
                        <span
                          aria-hidden
                          className='bg-foreground ring-background absolute -inset-y-1 w-0.5 -translate-x-1/2 rounded-full ring-2'
                          style={{ left: `${nowPosition}%` }}
                        />
                      )}
                    </div>
                  </li>
                )
              })}
            </ol>
          )}
          {!state && hovered && (
            <ChartFloatingTooltip active flip={hovered.flip} x={hovered.x} y={hovered.y}>
              <span className='font-medium'>{hovered.event.title}</span>
              <ChartTooltipItem
                color={hovered.event.color ?? 'var(--color-chart-2)'}
                name={hovered.event.calendar}
                value={formatTimeRange(hovered.event.start, hovered.event.end, timeZone)}
              />
            </ChartFloatingTooltip>
          )}
        </div>
        {!state && (
          <ul className='text-muted-foreground flex flex-wrap gap-x-4 gap-y-1 text-xs'>
            {calendars.map((calendar) => (
              <li key={calendar.name} className='flex items-center gap-1.5'>
                <EventSwatch color={calendar.color} />
                {calendar.name}
              </li>
            ))}
            <li aria-hidden className='flex items-center gap-1.5'>
              <span className='bg-foreground h-3 w-0.5 rounded-full' />
              Now
            </li>
          </ul>
        )}
      </section>
    </BlockStateProvider>
  )
}

export { Schedule4, exampleProps as schedule4ExampleProps, type Schedule4Props }
